// 0) Parse meta (string JSON) -> object
let meta = {};
try {
  meta = JSON.parse(String($json.meta || "").trim() || "{}");
} catch (e) {
  meta = {};
}

// 1) Extract model text from OpenAI node output
const raw = $json?.output?.[0]?.content?.[0]?.text ?? "";
const text = String(raw).trim();

// 2) Parse JSON output from model
let parsed = null;
let qa_ok = true;
let qa_status = "qa_ok";
let qa_message = "ok";

function fail(status, msg) {
  qa_ok = false;
  qa_status = status;
  qa_message = msg;
}

try {
  parsed = JSON.parse(text);
} catch (e) {
  fail("qa_fail_format", "Model output is not valid JSON");
}

// 3) Validate schema exactly
if (qa_ok && parsed) {
  const expected = ["id", "language", "length", "title", "body"];
  const keys = Object.keys(parsed);
  const hasAll = expected.every(k => keys.includes(k));
  const noExtra = keys.every(k => expected.includes(k));
  if (!hasAll || !noExtra) {
    fail("qa_fail_schema", "Keys must be exactly: id, language, length, title, body");
  }
}

// 4) Validate against meta (parsed object)
if (qa_ok && parsed) {
  // Normalizar valores para comparación (convertir a mayúsculas para case-insensitive)
  const parsedId = String(parsed.id || "").trim();
  const metaId = String(meta.id || "").trim();

  const parsedLang = String(parsed.language || "").trim().toUpperCase();
  const metaLang = String(meta.language || "").trim().toUpperCase();

  const parsedLen = String(parsed.length || "").trim().toLowerCase();
  const metaLen = String(meta.length || "").trim().toLowerCase();

  if (parsedId !== metaId) {
    fail("qa_fail_mismatch", `id mismatch (got "${parsedId}", expected "${metaId}")`);
  }
  if (parsedLang !== metaLang) {
    fail("qa_fail_mismatch", `language mismatch (got "${parsedLang}", expected "${metaLang}")`);
  }
  if (parsedLen !== metaLen) {
    fail("qa_fail_mismatch", `length mismatch (got "${parsedLen}", expected "${metaLen}")`);
  }
}

// 5) Title rules
if (qa_ok && parsed) {
  const title = String(parsed.title || "").trim();
  const titleWords = title.split(/\s+/).filter(Boolean).length;
  if (titleWords < 5 || titleWords > 12) {
    fail("qa_fail_title", `title must be 5-12 words (got ${titleWords})`);
  }
}

// 6) Body rules
if (qa_ok && parsed) {
  const body = String(parsed.body || "").trim();
  const words = body.split(/\s+/).filter(Boolean).length;
  const isShort = String(meta.length || "").trim().toLowerCase() === "short";
  const min = isShort ? 90 : 180;
  const max = isShort ? 140 : 260;
  if (words < min || words > max) {
    fail("qa_fail_length", `body words out of range (${min}-${max}), got ${words}`);
  }
  if (!body.includes("\n\n")) {
    fail("qa_fail_paragraphs", "body must have paragraphs separated by a blank line");
  }
}

// Asegurar que parsed siempre sea un objeto
if (!parsed) {
  parsed = { title: "", body: "" };
}

// 7) Return item for next nodes
return {
  json: {
    id: meta.id ?? "",
    topic: meta.topic ?? "",
    audience: meta.audience ?? "",
    language: meta.language ?? "",
    length: meta.length ?? "",
    title: parsed.title ?? "",
    body: parsed.body ?? "",
    qa_ok,
    qa_status,
    qa_message,
    generated_at: new Date().toISOString(),
    raw_response: text,
  }
};

// Filtrar SOLO los no procesados
items = items.filter(item => {
  const v = (item.json.n8n_processed_at ?? '').toString().trim();
  return v === '';
});

const allowedLanguages = new Set(['EN', 'ES']);
const allowedLengths = new Set(['short', 'medium']);

function norm(v) {
  return (v ?? '').toString().trim();
}

function pickRowNumber(row) {
  return (
    row.row_number ??
    row.rowNumber ??
    row._rowNumber ??
    row.row ??
    row.__rowNum ??
    null
  );
}

const processedAt = new Date().toISOString();

return items.map((item) => {
  const row = item.json;

  const id = norm(row.id);
  const topic = norm(row.topic);
  const audience = norm(row.audience);
  const language = norm(row.language).toUpperCase();
  const length = norm(row.length).toLowerCase();

  const errors = [];
  if (!id) errors.push({ field: 'id', message: 'missing id' });
  if (!topic) errors.push({ field: 'topic', message: 'missing topic' });
  if (!audience) errors.push({ field: 'audience', message: 'missing audience' });
  if (!language) errors.push({ field: 'language', message: 'missing language' });
  else if (!allowedLanguages.has(language)) {
    errors.push({ field: 'language', message: `invalid language: ${language}` });
  }
  if (!length) errors.push({ field: 'length', message: 'missing length' });
  else if (!allowedLengths.has(length)) {
    errors.push({ field: 'length', message: `invalid length: ${length}` });
  }

  const is_valid = errors.length === 0;
  const hasError = !is_valid;
  const error_fields = errors.map(e => e.field);
  const error_messages = errors.map(e => e.message);

  item.json = {
    ...row,
    id,
    topic,
    audience,
    language,
    length,
    // NO marcar n8n_processed_at aquí
    is_valid,
    hasError,
    step: 'validation',
    status: is_valid ? 'ok' : 'error',
    error_field: hasError ? error_fields.join('|') : '',
    message: hasError ? error_messages.join(' | ') : '',
    timestamp: processedAt,
    row_number: pickRowNumber(row),
  };

  return item;
});

const { id, topic, audience, language, length } = $json;

return {
  json: { 
    id,
    topic,
    audience,
    language,
    length,
    meta: JSON.stringify({ id, topic, audience, language, length })
  }
};

// Obtener la respuesta del modelo
const modelOutput = $json.output;

// Obtener los datos del nodo anterior (Code in JavaScript)
const previousData = $("Add meta field").item.json;

// Combinar todo
return {
  json: {
    ...previousData,  // incluye id, topic, audience, language, length, meta
    output: modelOutput  // incluye la respuesta del modelo
  }
};
